    const channel = supabase.channel(`tracking:vol_${user.id}`, {
       config: { broadcast: { ack: false } }
    });

    channel.subscribe((status) => {
      if (status !== 'SUBSCRIBED') return;

      const watchId = navigator.geolocation.watchPosition(
        (pos) => {
           // Broadcast to all donors that are listening for this volunteer
           channel.send({
             type: 'broadcast',
             event: 'location',
             payload: { lat: pos.coords.latitude, lng: pos.coords.longitude }
           });
        },
        (err) => {
           console.warn('Live tracking warning:', err);
           if (err.code === 1) { // PERMISSION_DENIED
               toast.error("ΓÜá∩╕Å Location Access Denied. The donor cannot track your arrival!", { duration: 6000 });
           }
        },
        { enableHighAccuracy: true, maximumAge: 0, timeout: 5000 }
      );

      return () => navigator.geolocation.clearWatch(watchId);
    });

    return () => {
       supabase.removeChannel(channel);
    };
