                        <div className="flex justify-between text-[11px] font-bold uppercase mb-2">
                           <span style={{ color: T.textSecondary }}>{s.l}</span>
                           <span style={{ color: T.textPrimary }}>{s.v}</span>
                        </div>
                        <div className="h-2 w-full rounded-full overflow-hidden" style={{ background: T.surfaceMid, border: `1px solid ${T.border}` }}>
                           <div className="h-full rounded-full" style={{ width: s.v === 'Elite' ? '100%' : s.v, background: s.c }} />
                        </div>
                      </div>
                    ))}
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};
